"""Write small, public-safe outputs for the website and the Power BI rebuild.

Refuses to run on anything but the synthetic dataset unless explicitly told to,
because the website is public. Outputs contain daily or weekly aggregates only:
no device names, no record-level timestamps.
"""

from __future__ import annotations

import json
from pathlib import Path

import numpy as np
import pandas as pd

from .metrics import BY_KEY, METRICS
from .transform import arithmetic_mean_by_day, naive_sum_by_day

SYNTHETIC_NOTICE = (
    "Synthetic demonstration data generated by apple_health.synthetic (seed {seed}). "
    "These are not real measurements of any person."
)


def _r(x, nd=2):
    if x is None or (isinstance(x, float) and (np.isnan(x) or np.isinf(x))):
        return None
    return round(float(x), nd)


def _energy_mean(levels: pd.Series) -> float | None:
    levels = levels.dropna()
    if levels.empty:
        return None
    return float(10 * np.log10(np.mean(np.power(10.0, levels / 10.0))))


def weekly(daily: pd.DataFrame) -> pd.DataFrame:
    """Weekly view. Additive metrics become average per day, not weekly totals,
    so a week with a missing day is not penalised."""
    d = daily.set_index("date")
    week = d.index.to_period("W-SUN").start_time
    rows = []
    for wk, g in d.groupby(week):
        row = {"week": wk.date().isoformat(), "days": int(len(g))}
        for m in METRICS:
            if m.key not in g:
                continue
            s = g[m.key]
            if m.aggregation == "energy_mean":
                row[m.key] = _r(_energy_mean(s), 1)
            elif m.aggregation == "last":
                s = s.dropna()
                row[m.key] = _r(s.iloc[-1]) if len(s) else None
            else:
                row[m.key] = _r(s.mean(), 2)
        rows.append(row)
    return pd.DataFrame(rows)


def kpis(daily: pd.DataFrame) -> list[dict]:
    def mean(key):
        return daily[key].mean() if key in daily else np.nan

    def window_change(key, n=30):
        s = daily[key].dropna() if key in daily else pd.Series(dtype=float)
        if len(s) < 2 * n:
            return None
        return s.tail(n).mean() - s.head(n).mean()

    vo2 = daily["vo2max"].dropna() if "vo2max" in daily else pd.Series(dtype=float)
    return [
        {"key": "steps", "group": "mobility", "label": "Average daily steps",
         "value": _r(mean("steps"), 0), "unit": "steps",
         "definition": "Mean of daily step totals after watch/phone de-duplication, over days with any step data."},
        {"key": "active_energy_kcal", "group": "activity", "label": "Average daily active energy",
         "value": _r(mean("active_energy_kcal"), 0), "unit": "kcal",
         "definition": "Mean of daily active-energy totals (sum per day, then average across days)."},
        {"key": "exercise_min", "group": "activity", "label": "Average daily exercise",
         "value": _r(mean("exercise_min"), 1), "unit": "min",
         "definition": "Mean of daily exercise-minute totals over days with watch data."},
        {"key": "stand_hours", "group": "activity", "label": "Average stand hours",
         "value": _r(mean("stand_hours"), 1), "unit": "hours",
         "definition": "Mean count of distinct hours per day marked 'Stood'."},
        {"key": "resting_hr_bpm", "group": "cardio", "label": "Average resting heart rate",
         "value": _r(mean("resting_hr_bpm"), 1), "unit": "bpm",
         "definition": "Daily mean of resting-HR estimates, averaged across days. Never summed."},
        {"key": "resting_hr_change", "group": "cardio", "label": "Resting HR change",
         "value": _r(window_change("resting_hr_bpm"), 1), "unit": "bpm",
         "definition": "Mean of the last 30 days with data minus mean of the first 30 days."},
        {"key": "hrv_sdnn_ms", "group": "cardio", "label": "Average HRV (SDNN)",
         "value": _r(mean("hrv_sdnn_ms"), 1), "unit": "ms",
         "definition": "Daily mean of SDNN readings, averaged across days."},
        {"key": "vo2max", "group": "cardio", "label": "Latest VO2 max estimate",
         "value": _r(vo2.iloc[-1] if len(vo2) else None, 1), "unit": "mL/min·kg",
         "definition": "Most recent daily VO2 max estimate in the period (estimates are sparse)."},
        {"key": "walking_speed_mph", "group": "mobility", "label": "Average walking speed",
         "value": _r(mean("walking_speed_mph"), 2), "unit": "mph",
         "definition": "Daily mean walking speed after converting km/hr records to mph."},
        {"key": "step_length_in", "group": "mobility", "label": "Average step length",
         "value": _r(mean("step_length_in"), 1), "unit": "in",
         "definition": "Daily mean walking step length, averaged across days."},
        {"key": "env_audio_dba", "group": "environment", "label": "Typical environmental sound",
         "value": _r(_energy_mean(daily.get("env_audio_dba", pd.Series(dtype=float))), 1), "unit": "dBA",
         "definition": "Energy average of daily sound levels (logarithmic, not arithmetic)."},
        {"key": "headphone_audio_dba", "group": "environment", "label": "Typical headphone level",
         "value": _r(_energy_mean(daily.get("headphone_audio_dba", pd.Series(dtype=float))), 1), "unit": "dBA",
         "definition": "Energy average of daily headphone levels on days with listening."},
    ]


def aggregation_audit(records: pd.DataFrame, daily: pd.DataFrame) -> dict:
    """Quantify what the original report's implicit aggregations would show."""
    d = daily.set_index("date")

    naive_rhr = naive_sum_by_day(records, "resting_hr_bpm")
    rhr = d["resting_hr_bpm"].reindex(naive_rhr.index)
    multi = naive_rhr[(naive_rhr - rhr).abs() > 0.5]

    naive_steps = naive_sum_by_day(records, "steps")
    steps = d["steps"].reindex(naive_steps.index)

    arith_db = arithmetic_mean_by_day(records, "env_audio_dba")
    energy_db = d["env_audio_dba"].reindex(arith_db.index)

    # A month-long window for the chart that compares the two resting-HR methods.
    window = naive_rhr.loc["2025-03-01":"2025-03-31"]
    comparison = [
        {
            "date": idx.date().isoformat(),
            "implicit_sum": _r(window.loc[idx], 1),
            "daily_mean": _r(d.loc[idx, "resting_hr_bpm"], 1),
        }
        for idx in window.index
    ]

    return {
        "resting_hr": {
            "days": int(len(naive_rhr)),
            "days_with_multiple_estimates": int(len(multi)),
            "max_implicit_sum": _r(naive_rhr.max(), 0),
            "max_daily_mean": _r(rhr.max(), 1),
            "march_comparison": comparison,
        },
        "steps": {
            "avg_naive_sum": _r(naive_steps.mean(), 0),
            "avg_deduplicated": _r(steps.mean(), 0),
            "inflation_pct": _r((naive_steps.mean() / steps.mean() - 1) * 100, 1),
        },
        "environmental_audio": {
            "avg_daily_gap_db": _r((energy_db - arith_db).mean(), 2),
            "max_daily_gap_db": _r((energy_db - arith_db).max(), 2),
        },
    }


def write_outputs(
    records: pd.DataFrame,
    daily: pd.DataFrame,
    quality: dict,
    manifest: dict,
    site_dir: Path,
    sample_dir: Path,
    allow_non_synthetic: bool = False,
) -> list[Path]:
    if not manifest.get("synthetic") and not allow_non_synthetic:
        raise PermissionError(
            "Refusing to export non-synthetic data to the public website. "
            "Review privacy first, then pass allow_non_synthetic=True deliberately."
        )
    site_dir.mkdir(parents=True, exist_ok=True)
    sample_dir.mkdir(parents=True, exist_ok=True)

    notice = SYNTHETIC_NOTICE.format(seed=manifest.get("seed"))
    metrics_meta = [
        {"key": m.key, "label": m.label, "unit": m.unit, "aggregation": m.aggregation, "group": m.group}
        for m in METRICS
        if m.key in daily
    ]

    daily_out = daily.copy()
    daily_out["date"] = daily_out["date"].dt.strftime("%Y-%m-%d")
    for m in METRICS:
        if m.key in daily_out:
            nd = 0 if m.key in ("steps", "active_energy_kcal", "flights_climbed") else 2
            daily_out[m.key] = daily_out[m.key].round(nd)

    summary = {
        "synthetic": True,
        "notice": notice,
        "generator": {k: manifest[k] for k in ("seed", "records", "days") if k in manifest},
        "period": quality["date_range"],
        "metrics": metrics_meta,
        "kpis": kpis(daily),
        "quality": quality,
        "aggregation_audit": aggregation_audit(records, daily),
    }

    written = []
    payloads = {
        "summary.json": summary,
        "weekly.json": {"synthetic": True, "notice": notice,
                        "rows": weekly(daily).replace({np.nan: None}).to_dict(orient="records")},
    }
    for name, payload in payloads.items():
        path = site_dir / name
        path.write_text(json.dumps(payload, indent=1, ensure_ascii=False) + "\n", encoding="utf-8")
        written.append(path)

    csv_path = sample_dir / "daily_metrics_synthetic.csv"
    daily_out.to_csv(csv_path, index=False)
    written.append(csv_path)
    written.extend(write_powerbi_tables(daily, sample_dir))
    return written


def write_powerbi_tables(daily: pd.DataFrame, out_dir: Path) -> list[Path]:
    """Star schema for the Power BI rebuild: one long fact and two dimensions.

    fact_daily_metric  grain: one row per date × metric with a value
    dim_metric         grain: one row per metric, carries the aggregation rule
    dim_date           grain: one row per calendar day in the fact's range
    """
    keys = [m.key for m in METRICS if m.key in daily]
    fact = daily.melt(id_vars="date", value_vars=keys, var_name="metric", value_name="value")
    fact = fact.dropna(subset=["value"]).sort_values(["date", "metric"])
    fact["date"] = fact["date"].dt.strftime("%Y-%m-%d")
    fact["value"] = fact["value"].round(3)

    dim_metric = pd.DataFrame(
        [
            {"metric": m.key, "label": m.label, "group": m.group, "unit": m.unit,
             "daily_aggregation": m.aggregation, "hk_type": m.hk_type}
            for m in METRICS
            if m.key in daily
        ]
    )

    dates = pd.date_range(daily["date"].min(), daily["date"].max(), freq="D")
    dim_date = pd.DataFrame(
        {
            "date": dates.strftime("%Y-%m-%d"),
            "year": dates.year,
            "quarter": dates.quarter,
            "month": dates.month,
            "month_name": dates.strftime("%b"),
            "iso_week": dates.isocalendar().week.to_numpy(),
            "week_start": (dates - pd.to_timedelta(dates.dayofweek, unit="D")).strftime("%Y-%m-%d"),
            "day_of_week": dates.dayofweek + 1,
            "day_name": dates.strftime("%a"),
            "is_weekend": dates.dayofweek >= 5,
        }
    )

    paths = []
    for name, frame in (("fact_daily_metric", fact), ("dim_metric", dim_metric), ("dim_date", dim_date)):
        path = out_dir / f"{name}.csv"
        frame.to_csv(path, index=False)
        paths.append(path)
    return paths


__all__ = ["write_outputs", "weekly", "kpis", "aggregation_audit", "BY_KEY"]
